function WaitlistForm({compact=false}:{compact?:boolean}){const [email,setEmail]=useState('');const [state,setState]=useState<'idle'|'sending'|'success'|'error'>('idle');const [errorMessage,setErrorMessage]=useState('');const [website,setWebsite]=useState('');async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(state==='sending')return;setState('sending');setErrorMessage('');try{const r=await fetch('/api/waitlist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.trim(),website,source:compact?'newsletter':'early-access'})});const body=await r.json().catch(()=>null);if(!r.ok)throw Error(typeof body?.error==='string'?body.error:'Could not save your email. Please try again.');setState('success');setEmail('')}catch(e){setErrorMessage(e instanceof Error?e.message:'Could not save your email. Please try again.');setState('error')}}return <div className={compact?'form-holder compact':'form-holder'}><form onSubmit={submit} className="waitlist-form"><label className="sr-only" htmlFor={compact?'footer-email':'hero-email'}>Email address</label><input id={compact?'footer-email':'hero-email'} name="email" autoComplete="email" required type="email" maxLength={254} placeholder="Enter your email address" value={email} onChange={e=>{setEmail(e.target.value);if(state!=='sending')setState('idle')}} disabled={state==='sending'}/><div aria-hidden="true" style={{position:'absolute',width:1,height:1,overflow:'hidden',clipPath:'inset(50%)'}}><label htmlFor={compact?'footer-website':'hero-website'}>Leave this field empty</label><input id={compact?'footer-website':'hero-website'} name="website" type="text" autoComplete="off" tabIndex={-1} value={website} onChange={e=>setWebsite(e.target.value)}/></div><button type="submit" disabled={state==='sending'}>{state==='sending'?'Joining…':state==='success'?'Subscribed ✓':compact?'Subscribe':'Join the waitlist'} <ArrowUpRight size={17}/></button></form><div className="form-note" role="status" aria-live="polite">{state==='success'?'Thanks! Your email has been added to our updates list.':state==='error'?errorMessage:compact?'Occasional product news and launch updates. Unsubscribe anytime.':'No spam. Launch updates only. Unsubscribe anytime.'}</div></div>}

