function CommandCenter(){
 const [mode,setMode]=useState(0),[prompt,setPrompt]=useState(commandModes[0].prompt),[option1,setOption1]=useState(commandModes[0].options1[0]),[option2,setOption2]=useState(commandModes[0].options2[0]),[variation,setVariation]=useState(0),[feedback,setFeedback]=useState('');
 const m=commandModes[mode];
 const choose=(i:number)=>{const n=commandModes[i];setMode(i);setPrompt(n.prompt);setOption1(n.options1[0]);setOption2(n.options2[0]);setVariation(0);setFeedback('')};
 const preview=()=>{setVariation(v=>(v+1)%4);setFeedback('Matching concept preview updated.')};
 return <section className="section command-section command-v1" id="studio"><div className="shell"><div className="command-heading"><SectionEyebrow>SECTION 04 / THE AI COMMAND CENTER</SectionEyebrow><h2>Everything you imagine.<br/><span className="gradient-text">One powerful workspace.</span></h2><p>Explore eight intelligent studios, each with its own creative controls and a matching output experience.</p></div><div className="command-frame"><div className="command-top"><div className="command-dots"><i/><i/><i/></div><div className="command-address">✳ XNOVAH AI</div><span className="command-status">COMMAND CENTER / V1</span></div><div className="command-layout"><aside className="command-sidebar"><div className="command-logo">✳ <b>xnovah</b></div><div className="command-sidebar-label">AI STUDIOS</div>{commandModes.map((item,i)=><button key={item.name} className={'command-nav '+(mode===i?'active':'')} onClick={()=>choose(i)}><span>{item.symbol}</span>{item.name}</button>)}</aside><div className="command-main"><div className="command-toolbar"><div><small>{m.name.toUpperCase()} / STUDIO</small><h3>{m.title}</h3><p className="command-v1-desc">{m.description}</p></div></div><div className="command-v1-columns"><div className="command-v1-panel"><div className="command-v1-panel-head">✦ SMART INPUT</div><div className="command-v1-panel-body"><label htmlFor="command-v1-prompt">Your creative brief</label><textarea id="command-v1-prompt" value={prompt} onChange={e=>setPrompt(e.target.value)}/><div className="command-v1-options"><div><label htmlFor="command-v1-opt1">{m.label1}</label><select id="command-v1-opt1" value={option1} onChange={e=>setOption1(e.target.value)}>{m.options1.map(o=><option key={o}>{o}</option>)}</select></div><div><label htmlFor="command-v1-opt2">{m.label2}</label><select id="command-v1-opt2" value={option2} onChange={e=>setOption2(e.target.value)}>{m.options2.map(o=><option key={o}>{o}</option>)}</select></div></div><button className="command-v1-primary" onClick={preview}>✦ Preview matching output ↗</button><button className="command-v1-button" onClick={()=>choose(mode)}>↺ Reset studio</button><div className="command-v1-feedback" role="status">{feedback}</div></div></div><div className="command-v1-panel"><div className="command-v1-panel-head">◈ MATCHED OUTPUT</div><div className="command-v1-panel-body"><div className="command-v1-result">
{m.type==='writer'&&<div className="command-v1-paper"><small>✳ XNOVAH / LAUNCH COPY</small><h4>Imagine more. Create beyond.</h4><p>Meet a new creative universe where your boldest ideas find room to grow. One intelligent space. Endless possibilities.</p></div>}
{m.type==='image'&&<><div className="command-v1-art" style={{filter:`hue-rotate(${variation*30}deg)`}}><div className="command-v1-orb"/></div><p className="command-v1-caption">{option1} concept · Lavender / Chrome · Variation {variation+1} · {option2}</p></>}
{m.type==='video'&&<><div className="command-v1-art command-v1-video"><span>▶</span></div><p className="command-v1-caption">Video storyboard concept · {option2} · No playable video attached</p></>}
{m.type==='chat'&&<><div className="command-v1-bubble">{prompt}</div><div className="command-v1-bubble alt"><strong>✳ Xnovah Assistant</strong><p>01 / Create Beyond — ambitious and futuristic.</p><p>02 / Creative Universe — connected and expressive.</p><p>03 / Made for Imagination — warm and human.</p></div></>}
{m.type==='code'&&<><pre className="command-v1-code">{'<button class="xnovah-btn">\n  Create beyond ↗\n</button>'}</pre><div className="command-v1-node">Create beyond ↗</div></>}
{m.type==='agents'&&<><div className="command-v1-node">✳ Define objective</div><div className="command-v1-arrow">↓</div><div className="command-v1-node">✎ Draft creative content</div><div className="command-v1-arrow">↓</div><div className="command-v1-node">◈ Review workflow</div></>}
{m.type==='voice'&&<><div className="command-v1-wave">▂ ▅ ▇ ▃ ▆ █ ▄ ▇ ▂</div><p className="command-v1-caption">{prompt}</p><p className="command-v1-caption">Voice preview concept — no audio attached.</p></>}
{m.type==='research'&&<><div className="command-v1-node command-v1-research"><strong>RESEARCH OUTLINE</strong><p>{prompt}</p></div><div className="command-v1-node">01 / Market landscape</div><div className="command-v1-node">02 / Emerging trends</div><div className="command-v1-node">03 / Sources and verification</div></>}
</div><div className="command-v1-actions"><button className="command-v1-button" onClick={()=>{if(navigator.clipboard?.writeText){navigator.clipboard.writeText(prompt).then(()=>setFeedback('Prompt copied.')).catch(()=>setFeedback('Clipboard unavailable.'))}else setFeedback('Clipboard unavailable.')}}>⧉ Copy prompt</button><button className="command-v1-button" onClick={preview}>↻ Regenerate preview</button></div></div></div></div></div></div></div><div className="command-bottom"><span>✳ PRODUCT EXPERIENCE / INTERACTIVE DESIGN CONCEPT</span><a href="#waitlist">Get early access <ArrowUpRight size={15}/></a></div><p className="command-disclaimer">Interactive front-end concept. Outputs are curated examples, not live AI generations. Video and voice are represented by sample interfaces.</p></div></section>
}
